"use client"

import * as React from "react"
import { Button, ButtonSize, ButtonVariant } from "@/registry/react/button"
import { useCopyToClipboard } from "@/hooks/use-copy-to-clipboard"
import { cn } from "cn"

import "./copy-button.css"

function CopyIcon() {
  return (
    <svg
      width="16"
      height="16"
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
    >
      <path
        d="M5.5 5.5V3.75A1.75 1.75 0 0 1 7.25 2h5A1.75 1.75 0 0 1 14 3.75v5A1.75 1.75 0 0 1 12.25 10.5H10.5"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
      />
      <rect
        x="2"
        y="5.5"
        width="8.5"
        height="8.5"
        rx="1.75"
        stroke="currentColor"
        strokeWidth="1.5"
      />
    </svg>
  )
}

function CheckIcon() {
  return (
    <svg
      width="16"
      height="16"
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
    >
      <path
        d="M3 8.5l3.25 3.25L13 4.75"
        pathLength={1}
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

type CopyTarget = string | React.RefObject<HTMLElement | null>
type CopyValue = string | (() => string)

function resolveText(value?: CopyValue, target?: CopyTarget): string | null {
  if (typeof value === "function") return value()
  if (value != null) return value

  if (target) {
    const element =
      typeof target === "string"
        ? document.querySelector<HTMLElement>(target)
        : target.current

    if (!element) return null

    if (
      element instanceof HTMLInputElement ||
      element instanceof HTMLTextAreaElement
    ) {
      return element.value
    }

    return element.textContent
  }

  return null
}

export interface CopyButtonProps extends Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "value" | "onCopy"
> {
  /** Text to copy, or a function that returns it at click time. */
  value?: CopyValue
  /** Element to copy from: a ref or a CSS selector. Ignored if `value` is set. */
  target?: CopyTarget
  copiedText?: string
  /** How long the copied state stays visible, in ms. */
  timeout?: number
  variant?: ButtonVariant
  size?: ButtonSize
  onCopy?: (text: string) => void
  onCopyError?: (text: string) => void
}

export const CopyButton = React.forwardRef<HTMLButtonElement, CopyButtonProps>(
  (
    {
      value,
      target,
      children,
      copiedText = "Copied",
      timeout = 2000,
      variant = "outline",
      size = "default",
      className,
      onClick,
      onCopy,
      onCopyError,
      "aria-label": ariaLabel,
      ...props
    },
    ref
  ) => {
    const { copied, copy } = useCopyToClipboard(timeout)

    const handleClick = async (event: React.MouseEvent<HTMLButtonElement>) => {
      onClick?.(event)
      if (event.defaultPrevented) return

      const text = resolveText(value, target)
      if (text == null) return

      const ok = await copy(text)

      if (ok) onCopy?.(text)
      else onCopyError?.(text)
    }

    const label =
      ariaLabel ??
      (typeof children === "string" ? children : "Copy to clipboard")

    return (
      <Button
        ref={ref}
        variant={variant}
        size={size}
        className={cn("np-copy-button", className)}
        data-copied={copied ? "" : undefined}
        aria-label={copied ? copiedText : label}
        onClick={handleClick}
        {...props}
      >
        {/* Icon stack */}
        <span data-np-icon-stack>
          {/* Copy icon */}
          <span data-copy-icon>
            <CopyIcon />
          </span>
          {/* Copied icon */}
          <span data-copied-icon>
            <CheckIcon />
          </span>
        </span>

        {children != null && (
          <span data-np-label-stack>
            <span data-copy-label>{children}</span>
            <span data-copied-label>{copiedText}</span>
          </span>
        )}
      </Button>
    )
  }
)

CopyButton.displayName = "CopyButton"

/* nepui — Copy Button (extends np-button) */

.np-copy-button,
[data-np-copy-button] {
  --np-copy-duration: 300ms;
  --np-copy-ease: cubic-bezier(0.3, 0, 0, 1);
  --np-copy-blur: 10px;
  --np-copy-scale: 0.2;
}

/* Stacks: states sit on top of each other in one grid cell */

:is(.np-copy-button, [data-np-copy-button]) [data-np-icon-stack],
:is(.np-copy-button, [data-np-copy-button]) [data-np-label-stack] {
  display: inline-grid;
  place-items: center;
}

:is(.np-copy-button, [data-np-copy-button]) [data-np-icon-stack] > *,
:is(.np-copy-button, [data-np-copy-button]) [data-np-label-stack] > * {
  grid-area: 1 / 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;

  transition:
    opacity var(--np-copy-duration) var(--np-copy-ease),
    filter var(--np-copy-duration) var(--np-copy-ease),
    transform var(--np-copy-duration) var(--np-copy-ease);
}

/* Idle: "copied" hidden */

:is(.np-copy-button, [data-np-copy-button]) [data-copied-icon],
:is(.np-copy-button, [data-np-copy-button]) [data-copied-label] {
  opacity: 0;
  filter: blur(var(--np-copy-blur));
  transform: scale(var(--np-copy-scale));
  pointer-events: none;
}

/* Copied: swap */

:is(.np-copy-button, [data-np-copy-button])[data-copied] [data-copy-icon],
:is(.np-copy-button, [data-np-copy-button])[data-copied] [data-copy-label] {
  opacity: 0;
  filter: blur(var(--np-copy-blur));
  transform: scale(var(--np-copy-scale));
}

:is(.np-copy-button, [data-np-copy-button])[data-copied] [data-copied-icon],
:is(.np-copy-button, [data-np-copy-button])[data-copied] [data-copied-label] {
  opacity: 1;
  filter: blur(0);
  transform: scale(1);
}

/* Check icon draws itself */

:is(.np-copy-button, [data-np-copy-button]) [data-copied-icon] path {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  transition: stroke-dashoffset 300ms var(--np-copy-ease) 0ms;
}

:is(.np-copy-button, [data-np-copy-button])[data-copied]
  [data-copied-icon]
  path {
  stroke-dashoffset: 0;
  transition-delay: 80ms;
}

/* Copied color (for the neutral variants) */

:is(.np-button-outline, .np-button-ghost, .np-button-secondary):is(
    .np-copy-button,
    [data-np-copy-button]
  )[data-copied],
:is(
    .np-button[data-variant="outline"],
    .np-button[data-variant="ghost"],
    .np-button[data-variant="secondary"]
  ):is(.np-copy-button, [data-np-copy-button])[data-copied] {
  --np-button-color: var(--np-success);
  pointer-events: none;
}

@media (prefers-reduced-motion: reduce) {
  :is(.np-copy-button, [data-np-copy-button]) * {
    transition: none !important;
  }
}
